def transform(grid):
    """Translate the non-background pattern down by one row."""
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    out = [[bg] * w for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
            out[r + 1][c] = grid[r][c]
    return out
